import json, numpy as np
from test_uncentered_read import records, site_vecs, srcs, cats
with open('genref_trace_plan.json') as f: plan = json.load(f)
ctx_map = {}
for ref, data in plan.items():
    for p, cat, tok, nxt, ctx in data['details']:
        ctx_map[(ref, p)] = (tok, nxt, ctx)
# also load gen/0.json:0 tokens from token_stats_0.json to get next_tok & ctx for trace_16!
with open('acts/token_stats_0.json') as f: ts0 = json.load(f)
t0_toks = [t['tok'] for t in ts0[0]['tokens']]
for pinfo in records:
    if pinfo['src'] == 'gen/0.json:0':
        p = pinfo['pos']
        nxt = t0_toks[p+1] if p+1 < len(t0_toks) else 'EOF'
        ctx = ''.join(t0_toks[max(0, p-12):p+1])
        ctx_map[('gen/0.json:0', p)] = (pinfo['tok'], nxt, ctx)

for target_cat in ['closer_dot', 'missed_concl_dot', 'closer_nl', 'missed_concl_nl', 'doubt_onset']:
    print(f'\n=== {target_cat} ===')
    for i, r in enumerate(records):
        if r['cat'] == target_cat:
            tok, nxt, ctx = ctx_map.get((r['src'], r['pos']), (r['tok'], '?', r['tok']))
            print(f'  [{i:3d}] {r["src"]:14s}:{r["pos"]:5d} | tok={tok!r:8s} -> nxt={nxt!r:10s} | ctx={ctx[-55:]!r}')
